def arch_panel(name,x,y,z,w,h,material):
    r=w/2;spring=z+h-r
    vs=[(x-w/2,y,z),(x+w/2,y,z)]
    vs += [(x+math.cos(a)*r,y,spring+math.sin(a)*r) for a in [i*math.pi/16 for i in range(17)]]
    return mesh('Town_'+name,vs,[tuple(range(len(vs)))],P[material])
def arch_trim(x,y,z,w,h,material='stone',radius=.055):
